function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // character
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // clock
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 100, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 100);
  ctx.lineTo(W/2 - 100 + 30 * Math.sin(t), H/2 - 100 - 30 * Math.cos(t));
  ctx.stroke();

  // wedding ring
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2 - 100, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 - 100);
  ctx.lineTo(W/2 + 100 + 20 * Math.sin(t + Math.PI/2), H/2 - 100 - 20 * Math.cos(t + Math.PI/2));
  ctx.stroke();

  ctx.restore();
}
